figures.asymptoteSource:
// Two rows of five terms. Equal gaps above, gaps that multiply by the
// ratio below. Two-argument size fixes the output box exactly.
size(320,200);
for (int i=0; i<5; ++i) {
  pair P = (1.2*i, 0.8);
  pair Q = (0.3*i*i, -0.8);
  dot(P, black+2.5pt);
  dot(Q, black+2.5pt);
  label("$"+string(i+1)+"$", P, N);
  label("$"+string(i+1)+"$", Q, S);
}
label("equal gaps", (2.4, 1.7), N);
label("each gap a fixed multiple of the last", (2.4, -1.7), S);
